package com.dongqh.luckyhub.fulfillment.scheduler;
import com.dongqh.luckyhub.fulfillment.config.FulfillmentProperties;import com.dongqh.luckyhub.fulfillment.service.FulfillmentStateService;import com.dongqh.luckyhub.fulfillment.worker.FulfillmentWorker;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class FulfillmentScheduler {private final FulfillmentStateService state;private final FulfillmentWorker worker;private final FulfillmentProperties properties;public FulfillmentScheduler(FulfillmentStateService state,FulfillmentWorker worker,FulfillmentProperties properties){this.state=state;this.worker=worker;this.properties=properties;}@Scheduled(fixedDelayString="${luckyhub.fulfillment.poll-interval:5s}",initialDelayString="${luckyhub.fulfillment.initial-delay:60s}")public void poll(){state.recoverExpiredLeases(properties.recoveryBatchSize());worker.runBatch();}}
